#!/usr/bin/env bash
set -euo pipefail

: "${RYOKU_SRC:?set RYOKU_SRC to the checkout root}"
: "${RYOKU_PKGVER:?set RYOKU_PKGVER to the package version}"
: "${RYOKU_BUILD_DIR:?set RYOKU_BUILD_DIR to the build directory}"

stage_prebuilt() {
  [[ -n ${RYOKU_PREBUILT_DIR:-} ]] || return 1
  mkdir -p "$RYOKU_BUILD_DIR"
  cp -a "$RYOKU_PREBUILT_DIR/." "$RYOKU_BUILD_DIR/"
}

_repo=$RYOKU_SRC

package() {
  local cfg="$pkgdir/usr/share/ryoku/config"

  # Umbriel config tree: config.toml plus every required include. settings.toml
  # and rebinds.toml are generated by apply on first boot, like niri's, and are
  # not shipped; the bind template lives in the provider.
  install -d "$cfg/umbriel"
  cp -a "$_repo/ryoku/umbriel/." "$cfg/umbriel/"

  install -Dm644 "$_repo/ryoku/umbriel/umbriel-portals.conf" \
    "$cfg/xdg-desktop-portal/umbriel-portals.conf"

  chmod -R u=rwX,go=rX "$pkgdir/usr/share/ryoku"

  install -Dm755 "$RYOKU_BUILD_DIR/ryoku-wm-umbriel" \
    "$pkgdir/usr/bin/ryoku-wm-umbriel"

  if [[ $RYOKU_INIT_MODE == systemd ]]; then
    local unit="$pkgdir/usr/lib/systemd/user/umbriel.service.d"
    install -Dm644 "$_repo/ryoku/shell/systemd/user/umbriel.service.d/ryoku-bootstrap.conf" \
      "$unit/ryoku-bootstrap.conf"
    install -Dm644 "$_repo/ryoku/shell/systemd/user/umbriel.service.d/ryoku-session.conf" \
      "$unit/ryoku-session.conf"
    install -Dm644 "$_repo/ryoku/shell/systemd/user/umbriel.service.d/ryoku-wm-env.conf" \
      "$unit/ryoku-wm-env.conf"
  fi
}

case "${1:-}" in
build)
  stage_prebuilt && exit 0
  mkdir -p "$RYOKU_BUILD_DIR"
  cd "$_repo/ryoku/wm/umbriel"
  go build -mod=vendor -o "$RYOKU_BUILD_DIR/ryoku-wm-umbriel" .
  ;;
install)
  pkgdir=${2:?install requires a destination root}
  RYOKU_INIT_MODE=${3:?install requires systemd or runit}
  case "$RYOKU_INIT_MODE" in
    systemd|runit) ;;
    *) printf 'unsupported init mode: %s\n' "$RYOKU_INIT_MODE" >&2; exit 2 ;;
  esac
  package
  ;;
*)
  printf 'usage: %s <build|install DESTDIR systemd|runit>\n' "$0" >&2
  exit 2
  ;;
esac
